// Kiro balance reflex: after a push, command the policy to step in the direction the pelvis is drifting.
// Gains are in (m/s of command) per (m/s of pelvis velocity error).
import { Reflex } from './reflex.js';
import type { ReflexState } from './reflex.js';

const GAIN = 1.5;       // command m/s per m/s of velocity error
const DEADBAND = 0.15;  // m/s of velocity error ignored

export class KiroReflex extends Reflex {
  override command(s: ReflexState, base: ArrayLike<number>, out: Float64Array): void {
    const qw = s.qpos[3] as number, qx = s.qpos[4] as number, qy = s.qpos[5] as number, qz = s.qpos[6] as number;
    const yaw = Math.atan2(2 * (qw * qz + qx * qy), 1 - 2 * (qy * qy + qz * qz));
    const c = Math.cos(yaw), sn = Math.sin(yaw);
    const wx = s.qvel[0] as number, wy = s.qvel[1] as number;
    // world velocity into the yaw-aligned body frame
    const bx = c * wx + sn * wy, by = -sn * wx + c * wy;
    const ex = bx - (base[0] as number), ey = by - (base[1] as number);
    const mag = Math.hypot(ex, ey);
    let kx = 0, ky = 0;
    if (mag > DEADBAND) {
      const f = GAIN * (mag - DEADBAND) / mag;
      kx = ex * f; ky = ey * f;
    }
    out[0] = (base[0] as number) + kx;
    out[1] = (base[1] as number) + ky;
    out[2] = base[2] as number;
  }
}

